function normalizeRegistry(registry) {
  if (!registry || !registry.games || typeof registry.games !== 'object' || Array.isArray(registry.games)) return null;

  return {
    updatedAt: registry.updatedAt || null,
    games: Object.entries(registry.games)
      .filter(([, game]) => game && game.enabled)
      .sort(([, a], [, b]) => (a.order || 999) - (b.order || 999))
      .map(([slug, game]) => {
        const iconUrl = optimizeStudioImage(game.iconUrl);
        const coverUrl = optimizeStudioImage(game.coverUrl);
        return {
          ...game,
          id: slug,
          slug,
          iconUrl,
          coverUrl,
          description: game.localized && game.localized['en-US'] && game.localized['en-US'].description
            ? game.localized['en-US'].description
            : (game.description || game.name),
          platforms: (game.platforms || []).filter((platform) => {
            if (platform === 'Android') return game.androidStatus === 'live' && Boolean(game.androidUrl);
            if (platform === 'Web') return game.webStatus === 'live' && Boolean(game.webUrl || game.itchUrl);
            return true;
          }),
          privacyPolicy: game.privacyUrl || null,
          icon: iconUrl || coverUrl || null,
          storeLinks: {
            googlePlay: game.androidStatus === 'live' ? game.androidUrl : null,
            itch: game.webStatus === 'live' ? (game.itchUrl || game.webUrl) : null,
            youtube: game.trailerUrl || null,
          },
        };
      }),
  };
}

const optimizedImageNames = new Set([
  'LazyLovers.png', 'LogoSlothysBakery.png', 'MatchTheRunes.png', 'Mix2WordIcon.png',
  'PigYearLogo.png', 'PizzaMasterLogo.png', 'SlothysLogo.png'
]);

function optimizeStudioImage(url) {
  if (!url || typeof url !== 'string') return url || null;
  try {
    const parsed = new URL(url);
    const filename = parsed.pathname.split('/').pop();
    if (parsed.hostname === 'burningal15.github.io' && parsed.pathname.includes('/FatCatGameStudioWebPage/site-assets/') && optimizedImageNames.has(filename)) {
      parsed.pathname = parsed.pathname.replace(/\.png$/i, '.webp');
      return parsed.toString();
    }
  } catch (_) {
    return url;
  }
  return url;
}

module.exports = { normalizeRegistry, optimizeStudioImage };
