  }
};

export default {
  name: 'StudioLanding',
  data() {
    return {
      games: [],
      language: getInitialSiteLanguage(),
      activeFilter: 'all',
      menuOpen: false,
      filters: [{ id: 'all', label: 'games.all' }, { id: 'Android', label: 'games.mobile' }, { id: 'Web', label: 'games.browser' }],
      art: {
        logo: '/FatCatGameStudioWebPage/site-assets/fatcat-symbol.png',
        fullLogo: '/FatCatGameStudioWebPage/site-assets/fatcat-full-logo.png',
        bakery: '/FatCatGameStudioWebPage/site-assets/LogoSlothysBakery.png',
        pigyear: '/FatCatGameStudioWebPage/site-assets/PigYearLogo.png',
        mix2word: '/FatCatGameStudioWebPage/site-assets/Mix2WordIcon.png'
      }
    };
  },
  computed: {
    pressKitUrl() {
      return this.language === 'es' ? '/FatCatGameStudioWebPage/es/prensa/' : '/FatCatGameStudioWebPage/press/';
    },
    visibleGames() {
      return this.games.filter(game => this.activeFilter === 'all' || (game.platforms || []).includes(this.activeFilter));
    }
  },
  async created() {
    try {
      const response = await EventService.getEvents();
      this.games = response.data || [];
      this.$nextTick(this.observeReveals);
    } catch (error) {
      this.games = [];
    }
  },
  watch: {
    language() {
      this.updatePageMetadata();
    }
  },
  mounted() {
    this.updatePageMetadata();
    this.$nextTick(this.observeReveals);
  },
  methods: {
    t(key) { return translations[this.language][key] || translations.en[key] || key; },
    toggleLanguage() {
      this.language = this.language === 'en' ? 'es' : 'en';
    },
    scrollTo(id) {
      const target = document.getElementById(id);
      if (target) target.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' });
      this.menuOpen = false;
    },
    navigateTo(id) { this.scrollTo(id); },
    observeReveals() {
      const elements = this.$el.querySelectorAll('.reveal:not(.is-visible)');
      if ('IntersectionObserver' in window && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        const observer = new IntersectionObserver(entries => entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            observer.unobserve(entry.target);
          }
        }), { threshold: 0.12, rootMargin: '0px 0px -24px 0px' });
        elements.forEach(element => observer.observe(element));
      } else {
        elements.forEach(element => element.classList.add('is-visible'));
      }
    },
    updatePageMetadata() {
      document.documentElement.lang = this.language;
      const title = this.language === 'es' ? 'FatCat Game Studio — Videojuegos para distintas plataformas' : 'FatCat Game Studio — Games across platforms';
      document.title = title;
      const description = this.language === 'es'
        ? 'Creamos videojuegos con personalidad desde Perú para móvil, escritorio, navegador y consola.'
        : 'We create characterful games from Peru for mobile, desktop, browser and console.';
      this.setMeta('name', 'description', description);
      this.setMeta('property', 'og:title', title);
      this.setMeta('property', 'og:description', description);
      this.setMeta('property', 'og:locale', this.language === 'es' ? 'es_ES' : 'en_US');
      this.setMeta('name', 'twitter:title', title);
      this.setMeta('name', 'twitter:description', description);
    },
    setMeta(attribute, key, value) {
      const selector = `meta[${attribute}="${key}"]`;
      let meta = document.querySelector(selector);
      if (!meta) {
        meta = document.createElement('meta');
        meta.setAttribute(attribute, key);
        document.head.appendChild(meta);
      }
      meta.setAttribute('content', value);
    },
    keyFor(game) {
      const name = (game.name || '').toLowerCase();
      if (name.includes('mix2word')) return 'mix2word';
      if (name.includes('pig year')) return 'pigyear';
      if (name.includes('lazy lovers')) return 'lazylovers';
      if (name.includes('pizza')) return 'pizza';
      if (name.includes('bakery')) return 'bakery';
      if (name.includes('café') || name.includes('cafe')) return 'cafe';
      return 'runes';
    },
    artFor(game) {
      if (game.coverUrl || game.iconUrl) return game.coverUrl || game.iconUrl;
      const images = {
        mix2word: '/FatCatGameStudioWebPage/site-assets/Mix2WordIcon.png',
        pigyear: '/FatCatGameStudioWebPage/site-assets/PigYearLogo.png',
        lazylovers: '/FatCatGameStudioWebPage/site-assets/LazyLovers.png',
        pizza: '/FatCatGameStudioWebPage/site-assets/PizzaMasterLogo.png',
        bakery: '/FatCatGameStudioWebPage/site-assets/LogoSlothysBakery.png',
        cafe: '/FatCatGameStudioWebPage/site-assets/SlothysLogo.png',
        runes: '/FatCatGameStudioWebPage/site-assets/MatchTheRunes.webp'
      };
      return images[this.keyFor(game)] || this.art.logo;
    },
    nameFor(game) {
      const locale = this.language === 'es' ? 'es-ES' : 'en-US';
      return game.localized?.[locale]?.name || game.name;
    },
    descriptionFor(game) {
      const locale = this.language === 'es' ? 'es-ES' : 'en-US';
      return game.localized?.[locale]?.description || this.t('game.' + this.keyFor(game));
    },
    gameSeoHref(game) {
      const sourceId = game.slug || game.id || game.name;
      const slug = String(sourceId).replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
      const base = process.env.BASE_URL;
      return this.language === 'es' ? `${base}es/juegos/${slug}/` : `${base}games/${slug}/`;
    },
    genreFor(game) {
      const key = this.keyFor(game);
      const genres = { mix2word: 'genre.word', pigyear: 'genre.casual', lazylovers: 'genre.platformer', pizza: 'genre.learning', bakery: 'genre.learning', cafe: 'genre.casualLearning', runes: 'genre.memory' };
      return this.t(genres[key]);
    },
    platformLabel(game) {
      const platforms = game.platforms || [];
      if (platforms.includes('Android') && platforms.includes('Web')) return this.t('platform.androidWeb');
      if (platforms.includes('Android')) return this.t('platform.android');
      if (platforms.includes('Web')) return this.t('platform.web');
      return this.t('platform.other');
    },
  }
};
</script>

