export function detectSiteLanguage() {
  if (typeof navigator === 'undefined') return 'en';
  const primaryLanguage = (Array.isArray(navigator.languages) && navigator.languages[0]) || navigator.language || '';
  return primaryLanguage.trim().toLowerCase().startsWith('es') ? 'es' : 'en';
}

export function getInitialSiteLanguage() {
  // Always follow the current browser/device preference on a fresh visit.
  // A manual toggle applies only to the current page session.
  return detectSiteLanguage();
}
